FuncDef.Code:
//-------------------------------------------------------------------------------
// main
//-------------------------------------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = convertFragCoordsToUv(fragCoord);

    uv -= renderer_fxCenter;

    uv *= log(length(uv * renderer_paramA)) * renderer_paramB;

    uv *= renderer_fxScale;

    vec2 ind = floor(1. * uv);

    // mirror type 1
    uv *= mod(ind, 2.0) * 2.0 - 1.0;

    // mirror type 2
    //uv *= mod(ind + 1.0, 2.0) * 2.0 - 1.0;


    //vec4 thisPassOutput = texture(iChannel0, uv);
    vec4 prevPassOutput = texture(iChannel1, uv);

    vec4 col = prevPassOutput;

    col.a = 1.0;

    // output to screen
    fragColor = col;
}
